/** Shared language cases: original regression suite and automatic engine parity discovery. */
export const resource='class R : IDisposable {public int X;public R(int x){X=x;}public void Dispose(){Console.WriteLine(X);}}';
export const cases=[
 ['checked add catch','int x=2147483647;try{Console.WriteLine(checked(x+1));}catch(Exception e){Console.WriteLine("overflow");}','overflow\n'],
 ['checked multiply','int x=50000;try{checked{Console.WriteLine(x*x);}}catch(Exception e){Console.WriteLine("overflow");}','overflow\n'],
 ['checked subtract','int x=-2147483648;try{checked{Console.WriteLine(x-1);}}catch(Exception e){Console.WriteLine("overflow");}','overflow\n'],
 ['checked negate','int x=-2147483648;try{Console.WriteLine(checked(-x));}catch(Exception e){Console.WriteLine("overflow");}','overflow\n'],
 ['checked conversion','double x=2147483648.0;try{Console.WriteLine(checked((int)x));}catch(Exception e){Console.WriteLine("overflow");}','overflow\n'],
 ['checked conversion truncation','double x=-2147483648.9;Console.WriteLine(checked((int)x));','-2147483648\n'],
 ['unchecked nested','int x=2147483647;checked{unchecked{Console.WriteLine(x+1);}Console.WriteLine(unchecked(x+1));}','-2147483648\n-2147483648\n'],
 ['checked nested','int x=2147483647;unchecked{try{Console.WriteLine(checked(x+1));}catch(Exception e){Console.WriteLine(7);}}','7\n'],
 ['checked nonoverflow','int x=12;Console.WriteLine(checked((x+3)*2-1));','29\n'],
 ['checked compound array','int[] a=new int[]{2147483647};try{checked{a[0]++;}}catch(Exception e){}Console.WriteLine(a[0]);','2147483647\n'],
 ['checked setter not invoked on overflow','var c=new C();try{checked{c.X+=1;}}catch(Exception e){}Console.WriteLine(c.X);class C{public int X{get;set;}=2147483647;}','2147483647\n'],
 ['unchecked constant','const int x=unchecked(2147483647+1);Console.WriteLine(x);','-2147483648\n'],
 ['const expression patterns','const int n=2;int x=3;switch(x){case n+1:Console.WriteLine(7);break;default:break;}Console.WriteLine(x switch {n+1=>8,_=>0});','7\n8\n'],
 ['const string patterns','const string s="a"+"b";string x="ab";Console.WriteLine(x switch {s=>9,_=>0});','9\n'],
 ['int boundary literal','Console.WriteLine(checked(-2147483648));','-2147483648\n'],
 ['using statement','using(R r=new R(1)){Console.WriteLine(0);}'+resource,'0\n1\n'],
 ['using declaration','{using var r=new R(1);Console.WriteLine(0);}Console.WriteLine(2);'+resource,'0\n1\n2\n'],
 ['using multiple resources','using(R a=new R(1),b=new R(2)){Console.WriteLine(0);}'+resource,'0\n2\n1\n'],
 ['using declaration lifetimes','using var a=new R(1);using var b=new R(2);Console.WriteLine(0);'+resource,'0\n2\n1\n'],
 ['using null','using(R r=null){Console.WriteLine(0);}'+resource,'0\n'],
 ['using return','int F(){using var r=new R(1);return 42;}Console.WriteLine(F());'+resource,'1\n42\n'],
 ['using exception','try{using var r=new R(1);throw new Exception("x");}catch(Exception e){Console.WriteLine(e.Message);}'+resource,'1\nx\n'],
 ['using break continue','for(int i=0;i<3;i++){using var r=new R(i);if(i<1)continue;break;}'+resource,'0\n1\n'],
 ['using expression captures once','R r=new R(1);using(r){r=new R(2);}Console.WriteLine(r.X);'+resource,'1\n2\n'],
 ['using partial initializer failure','R Fail(){throw new Exception("fail");}try{using(R a=new R(1),b=Fail()){Console.WriteLine(0);}}catch(Exception e){Console.WriteLine(e.Message);}'+resource,'1\nfail\n'],
 ['using dispose throws','int F(){using var r=new R();return 42;}try{Console.WriteLine(F());}catch(Exception e){Console.WriteLine(e.Message);}class R:IDisposable{public void Dispose(){throw new Exception("dispose");}}','dispose\n'],
 ['outer resource disposed after inner dispose throws','try{using(R a=new R(1),b=new R(2)){} }catch(Exception e){Console.WriteLine(e.Message);} class R:IDisposable{public int X;public R(int x){X=x;}public void Dispose(){Console.WriteLine(X);if(X==2)throw new Exception("dispose");}}','2\n1\ndispose\n'],
 ['using GC protects captured resource','R r=new R(7);using(r){r=null;GC.Collect();}'+resource,'7\n'],
 ['using return reference survives cleanup GC','C F(){using var r=new R();return new C();}Console.WriteLine(F().X);class R:IDisposable{public void Dispose(){GC.Collect();}}class C{public int X=42;}','42\n'],
 ['fully qualified disposable','using var r=new R();class R:System.IDisposable{public void Dispose(){Console.WriteLine(1);}}','1\n'],
];
export const diagnosticCases=[
 ['default const overflow','Console.WriteLine(2147483647+1);','CS0220'],
 ['checked constant in unchecked','unchecked{Console.WriteLine(checked(2147483647+1));}','CS0220'],
 ['nonconstant const','int F(){return 1;}const int x=F();Console.WriteLine(x);','CS0133'],
 ['constant divide zero','int x=1/0;','CS0020'],
 ['missing Dispose','using var r=new R();class R:IDisposable{}','CS0535'],
 ['private Dispose','using var r=new R();class R:IDisposable{void Dispose(){}}','CS0535'],
 ['not IDisposable','using var r=new R();class R{public void Dispose(){}}','CS1674'],
 ['using reassignment','using var r=new R(1);r=new R(2);'+resource,'CS1656'],
 ['missing using initializer','using(R r){}'+resource,'CS0210'],
 ['multiple var','using(var r=new R(1),s=new R(2)){}'+resource,'CS0819'],
 ['duplicate constant switch','const int x=2;switch(3){case x+1:break;case 3:break;}','CS0152'],
];
export const languageFixtures=[
 ...cases.map(([name,source,output])=>({id:'release06/'+name,source,expected:{output}})),
 ...diagnosticCases.map(([name,source,code])=>({id:'release06/diagnostic/'+name,source,compileFailure:true,diagnosticCodes:[code]}))
];
